const r = await tools.exec_command({cmd:"deno eval '
import { LOOT_TABLES } from "./src/rules/data/lootTables.js";
import { ITEM_CATALOG } from "./src/rules/data/itemCatalog.js";
import { GEM_DEFS } from "./src/rules/data/gems.js";
import "./src/content/items/index.js";
import { allContentItems } from "./src/content/registry.js";
const catalog={...ITEM_CATALOG}; for(const [id,def] of allContentItems()) catalog[id]=def;
const itemRefs=new Set(), equipRefs=new Set(), gemRefs=new Set(), archRefs=new Set();
for(const t of Object.values(LOOT_TABLES)) for(const e of t.entries||[]) { if(e.type==="item") itemRefs.add(e.itemId); if(e.type==="equip") for(const id of e.pool||[]) equipRefs.add(id); if(e.type==="gem") {if(e.gemId) gemRefs.add(e.gemId); for(const id of e.materials||[]) gemRefs.add(`material:${id}`)} if(e.type==="archetype") archRefs.add(e.archetype); }
const all=Object.keys(catalog);
const equipment=all.filter(id=>catalog[id]?.catalogKind==="equipment");
const magic=all.filter(id=>catalog[id]?.catalogKind==="magic");
const reagents=all.filter(id=>catalog[id]?.tags?.some(t=>/reagent|material|ingredient|cooking_ingredient/.test(String(t))) || /^reagent_/.test(id));
const show=(name,ids,refs)=>{const missing=ids.filter(id=>!refs.has(id)); const covered=ids.filter(id=>refs.has(id)); console.log(name,JSON.stringify({total:ids.length,covered:covered.length,missing:missing.length,missingIds:missing},null,2));};
show("equipment",equipment,equipRefs); show("magic",magic,itemRefs); show("reagents",reagents,itemRefs); console.log("lootRefs",JSON.stringify({item:[...itemRefs].length,equip:[...equipRefs].length,gems:[...gemRefs],archetypes:[...archRefs]},null,2));
'","workdir":"/home/pjensen/Repos/JSHack","yield_time_ms":10000,"max_output_tokens":18000});
